package dev.redstoneengineering.physics;
import dev.redstoneengineering.block.*;import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;
/** Straight-line optical link with line-of-sight, channel filtering, alignment and finite power budget. */
public final class FreeSpaceOpticsKernel{private FreeSpaceOpticsKernel(){}public static void emit(ServerLevel l,BlockPos p,Direction d,int power,int channel){int remaining=Math.max(0,Math.min(15,power));for(int i=1;i<=48&&remaining>0;i++){BlockPos q=p.relative(d,i);if(!l.hasChunkAt(q))break;var s=l.getBlockState(q);if(s.getBlock() instanceof FreeSpaceOpticalReceiverBlock){boolean aligned=s.getValue(DirectionalSignalBlock.FACING)==d;boolean channelOk=s.getValue(FreeSpaceOpticalReceiverBlock.CHANNEL)==channel;if(aligned&&channelOk){int quality=Math.max(5,100-i*2);InformationRuntime.write(l,"free_optical",q,remaining,channel,true,quality);l.scheduleTick(q,s.getBlock(),1);}break;}if(!s.isAir())break;if(i%8==0)remaining--;}}}
